async def execute(envelop, agent):
    try:
        func_name = envelop.meta.get("function")
        if not func_name:
            envelop.payload["error"] = "Missing function name in meta.function"
            return envelop
        
        func = getattr(numpy, func_name, None)
        if func is None:
            for _, mod_name, _ in pkgutil.iter_modules(numpy.__path__):
                try:
                    mod = __import__(f"{library_name}.{mod_name}", fromlist=[func_name])
                    func = getattr(mod, func_name, None)
                    if func is not None:
                        break
                except:
                    pass
        
        if func is None:
            envelop.payload["error"] = f"{func_name} not found in numpy"
            return envelop
        
        result = func(**envelop.payload.get("args", {}))
        envelop.payload["result"] = str(result)
        envelop.payload["source"] = "numpy"
    except Exception as e:
        envelop.payload["error"] = str(e)
    return envelop
